<?php
if(!isset($manager,$user)){http_response_code(404);exit;}
$statusLabels=['inquiry'=>'Enquiry','hold'=>'Reservation','confirmed'=>'Confirmed','rejected'=>'Declined','cancelled'=>'Cancelled','expired'=>'Expired'];
$id=max(0,(int)($_GET['id']??$_GET['booking_id']??($error!==''?($_POST['return_id']??0):0)));
$booking=$id?($manager->query('SELECT * FROM bookings WHERE id=?',[$id])[0]??null):null;
if($id&&!$booking):?><p class="alert error">Booking not found.</p><?php endif;?>
<?php if($booking):?><div class="actions"><a href="<?=ae(au('bookings'))?>">← All bookings</a><span class="badge <?=ae($booking['status'])?>"><?=ae($statusLabels[$booking['status']])?></span></div>
<div class="grid"><section class="card"><h2><?=ae($booking['reference'])?></h2><dl><dt>Guest</dt><dd><?=ae($booking['name'])?></dd><dt>Email / phone</dt><dd><?=ae($booking['email']?:'No email')?> · <?=ae($booking['phone']?:'No phone')?></dd><dt>Stay</dt><dd><?=ae($booking['check_in'])?> → <?=ae($booking['check_out'])?> · <?=(int)$booking['guests']?> guests</dd><dt>Agreed total</dt><dd><?=money($booking['total_satang'])?></dd><dt>Created</dt><dd><?=ae($booking['created_at'])?> UTC</dd><?php if($booking['expires_at']):?><dt>Reservation expires</dt><dd><?=ae($booking['expires_at'])?> UTC</dd><?php endif;?></dl><?php if($booking['message']):?><h3>Guest message</h3><p><?=nl2br(ae($booking['message']))?></p><?php endif;?>
<?php $available=['inquiry'=>['hold'=>'Reserve dates','confirmed'=>'Confirm booking','rejected'=>'Decline enquiry'],'hold'=>['confirmed'=>'Confirm booking','cancelled'=>'Cancel reservation'],'confirmed'=>['cancelled'=>'Cancel booking']][$booking['status']]??[];if($available):form_start('transition','bookings',['id'=>$id,'return_id'=>$id]);select('status','Action',$available);input('hold_hours','Reservation hours',24,'number',false,'min="1" max="168"');?><button type="submit" data-confirm="Save this booking status?">Save status</button></form><p class="help">Confirmed stays and active reservations block dates. Enquiries do not. Conflicts are checked before saving.</p><?php endif;?></section>
<section class="card"><h2>Internal notes</h2><?php form_start('note','bookings',['id'=>$id,'return_id'=>$id]);textarea('note','Notes for staff',$booking['internal_note']);?><button>Save notes</button></form><h3>Payment record</h3><?php form_start('payment','bookings',['id'=>$id,'return_id'=>$id]);select('status','Payment status',['unpaid'=>'Unpaid','payment_instructions_sent'=>'Instructions sent','paid_manual'=>'Paid manually','refunded_manual'=>'Refunded manually'],$booking['payment_status']);?><button>Save payment status</button></form><p class="help">This is a manual record. No money is collected by the website.</p></section></div>
<?php if(in_array($booking['status'],['inquiry','hold','confirmed'],true)):?><section class="card"><h2>Change stay dates or agreed total</h2><p class="help">The price is recalculated using current rules and dates are checked again.</p><?php form_start('reschedule','bookings',['id'=>$id,'return_id'=>$id]);input('check_in','Check-in',$booking['check_in'],'date',true);input('check_out','Check-out',$booking['check_out'],'date',true);input('guests','Guests',$booking['guests'],'number',true,'min="1" max="100"');input('amount_thb','New agreed total THB (blank recalculates)','','text',false,'inputmode="decimal"');input('price_reason','Reason for a manual total','','text',false,'maxlength="300"');?><button data-confirm="Save the new stay dates and price?">Save stay and price</button></form><h3>Guest contact details</h3><?php form_start('guest_details','bookings',['id'=>$id,'return_id'=>$id]);input('name','Guest name',$booking['name'],'text',true,'maxlength="120"');input('email','Email',$booking['email'],'email');input('phone','Phone',$booking['phone'],'tel',false,'maxlength="40"');?><button>Save contact details</button></form></section><?php endif;?>
<section class="card"><h2>History and notifications</h2><?php $history=$manager->query('SELECT * FROM audit_log WHERE booking_id=? ORDER BY id DESC LIMIT 100',[$id]);?><ul class="timeline"><?php foreach($history as $event):?><li><?=ae($event['action'])?> · <?=ae($event['actor'])?><small> <?=ae($event['created_at'])?> UTC · <?=ae($event['status_from'])?> → <?=ae($event['status_to'])?></small></li><?php endforeach;?></ul>
<details><summary>Price snapshot</summary><pre><?=ae(json_encode(json_decode($booking['price_snapshot_json'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></details>
<?php $events=$manager->query('SELECT kind,status,attempts,created_at,last_error FROM notification_outbox WHERE event_key LIKE ? ORDER BY id DESC',['booking:'.$id.':%']);if($events):?><h3>Emails</h3><ul class="timeline"><?php foreach($events as $event):?><li><?=ae($event['kind'])?> · <span class="badge <?=ae($event['status'])?>"><?=ae($event['status'])?></span> · <?=(int)$event['attempts']?> attempts <small><?=ae($event['last_error'])?></small></li><?php endforeach;?></ul><?php endif;?>
<?php if(in_array($booking['status'],['rejected','cancelled','expired'],true)):form_start('anonymize','bookings',['id'=>$id,'return_id'=>$id]);?><button class="danger" data-confirm="Permanently remove this closed booking's personal information?">Anonymise personal information</button></form><?php endif;?></section>
<?php elseif(isset($_GET['new'])||($error!==''&&($_POST['action']??'')==='manual_booking')):?>
<section class="card"><h2>Register a manual booking</h2><p class="help">Use this for enquiries and stays arranged by phone or email. A confirmed booking blocks dates immediately.</p><?php form_start('manual_booking','bookings',['return_new'=>1]);input('name','Guest name','','text',true,'maxlength="120"');input('email','Email (optional)','','email',false,'maxlength="254"');input('phone','Phone (optional)','','tel',false,'maxlength="40"');input('check_in','Check-in',$_GET['date']??'','date',true);input('check_out','Check-out','','date',true);input('guests','Guests',1,'number',true,'min="1" max="100"');select('status','Initial status',['inquiry'=>'Enquiry','hold'=>'Reservation','confirmed'=>'Confirmed']);input('hold_hours','Reservation hours',24,'number',false,'min="1" max="168"');input('amount_thb','Agreed total THB (leave blank to calculate)','','text',false,'inputmode="decimal"');input('price_reason','Reason for agreed price','','text',false,'maxlength="300"');textarea('note','Internal note');checkbox('notify','Queue a confirmation email if this booking is confirmed');?><button data-confirm="Create this booking with the selected status?">Create booking</button><a href="<?=ae(au('bookings'))?>">Cancel</a></form></section>
<?php else:
$q=mb_substr(trim((string)($_GET['q']??$_GET['booking_q']??'')),0,100);$filterStatus=(string)($_GET['status']??$_GET['booking_status']??'');$from=(string)($_GET['from']??$_GET['booking_from']??'');$to=(string)($_GET['to']??$_GET['booking_to']??'');$page=max(1,min(10000,(int)($_GET['page']??1)));$where=[];$params=[];
if($q!==''){$where[]='(instr(lower(reference),lower(?))>0 OR instr(lower(name),lower(?))>0 OR instr(lower(email),lower(?))>0)';$params=[$q,$q,$q];}if(isset($statusLabels[$filterStatus])){$where[]='status=?';$params[]=$filterStatus;}
foreach(['from'=>$from,'to'=>$to]as $key=>$date)if(preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)){$where[]=$key==='from'?'check_out>?':'check_in<=?';$params[]=$date;}
$filter=$where?' WHERE '.implode(' AND ',$where):'';$count=(int)$manager->query('SELECT COUNT(*) AS n FROM bookings'.$filter,$params)[0]['n'];$rows=$manager->query('SELECT * FROM bookings'.$filter.' ORDER BY id DESC LIMIT 25 OFFSET '.(($page-1)*25),$params);
?><div class="actions"><a class="button" href="<?=ae(au('bookings',['new'=>1]))?>">Create booking</a><a class="button secondary" href="<?=ae(au('bookings',['export'=>1]))?>">Export CSV</a></div><section class="card"><form method="get" action="<?=ae(url('admin.php'))?>"><input type="hidden" name="view" value="bookings"><?php input('q','Reference, guest or email',$q);select('status','Status',[''=>'All statuses']+$statusLabels,$filterStatus);input('from','From',$from,'date');input('to','To',$to,'date');?><button>Search</button><a href="<?=ae(au('bookings'))?>">Clear</a></form><p class="help"><?=$count?> bookings match. Up to 25 per page.</p><div class="scroll"><table><thead><tr><th>Reference</th><th>Guest</th><th>Stay</th><th>Status</th><th>Total</th></tr></thead><tbody><?php foreach($rows as $booking):?><tr><td><a href="<?=ae(au('bookings',['id'=>$booking['id']]))?>"><?=ae($booking['reference'])?></a></td><td><?=ae($booking['name'])?><small><?=ae($booking['email'])?></small></td><td class="nowrap"><?=ae($booking['check_in'])?><small>to <?=ae($booking['check_out'])?> · <?=(int)$booking['guests']?> guests</small></td><td><span class="badge <?=ae($booking['status'])?>"><?=ae($statusLabels[$booking['status']])?></span></td><td class="nowrap"><?=money($booking['total_satang'])?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$rows):?><p class="empty">No bookings match these filters.</p><?php endif;?><nav class="pagination" aria-label="Booking pages"><?php $filters=['q'=>$q,'status'=>$filterStatus,'from'=>$from,'to'=>$to];if($page>1):?><a href="<?=ae(au('bookings',$filters+['page'=>$page-1]))?>">← Previous</a><?php endif;?><span>Page <?=$page?> of <?=max(1,(int)ceil($count/25))?></span><?php if($page*25<$count):?><a href="<?=ae(au('bookings',$filters+['page'=>$page+1]))?>">Next →</a><?php endif;?></nav></section>
<?php endif;?>
